const state={trips:[],trip:null,tab:'overview',page:'welcome',health:null,mapsConfig:null,busy:false,asking:false,mode:'local',uploading:false,showAssistant:false,showNotifications:false,showAddPlans:false,showFlight:false,showTrain:false,showPlace:null,liveRoute:null,locating:false,routeError:'',planDraft:'',optimisticQuestion:'',pendingQuestion:'',listening:false,liveStatus:null,monitoring:false,lastLiveCheck:0,sampleMonitoringTripId:null};
let speechInput=null,countdownTimer=null,mapsConfigLoader=null,googleMapsLoader=null,placeGoogleMap=null;
const $=s=>document.querySelector(s);
const escapeHTML=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const e=escapeHTML;
const ORIGIN_ZONE='America/Los_Angeles',DESTINATION_ZONE='Europe/London';
function tripDestinationZone(t=state.trip){const route=String(t?.facts?.['flight.route']?.value||t?.trip?.title||'').toLowerCase();return route.includes('santiago')||route.includes('chile')?'America/Santiago':DESTINATION_ZONE;}
function tripDestinationName(t=state.trip){return tripDestinationZone(t)==='America/Santiago'?'Santiago':'London';}
function commitmentZone(item,t=state.trip){const location=String(item?.location||'').toLowerCase(),origin=location.split(/\s+to\s+/)[0],text=`${item?.title||''} ${origin}`.toLowerCase();if(text.includes('san francisco')||text.includes('sfo'))return'America/Los_Angeles';if(text.includes('dallas')||text.includes('dfw'))return'America/Chicago';if(/santiago|calama|puerto natales|atacama|torres del paine|socaire|chile/.test(text))return'America/Santiago';return tripDestinationZone(t);}
function fmt(value,options={},zone=DESTINATION_ZONE){if(!value)return 'Not documented';const d=new Date(value);if(Number.isNaN(d.getTime()))return value;return d.toLocaleString('en-US',{timeZone:zone,month:'short',day:'numeric',hour:'numeric',minute:'2-digit',hour12:true,timeZoneName:'short',...options});}
function clock(value,zone=DESTINATION_ZONE){if(!value)return 'Not documented';const d=new Date(value);if(Number.isNaN(d.getTime()))return value;return d.toLocaleTimeString('en-US',{timeZone:zone,hour:'numeric',minute:'2-digit',hour12:true});}
function day(value,zone=DESTINATION_ZONE){if(!value)return '';const d=new Date(value);if(Number.isNaN(d.getTime()))return '';return d.toLocaleDateString('en-US',{timeZone:zone,weekday:'short',month:'short',day:'numeric'});}
function countdownModel(value,now=Date.now()){const target=new Date(value).getTime();if(!Number.isFinite(target))return null;const remaining=Math.max(0,target-now),totalSeconds=Math.floor(remaining/1000),days=Math.floor(totalSeconds/86400),hours=Math.floor(totalSeconds%86400/3600),minutes=Math.floor(totalSeconds%3600/60),seconds=totalSeconds%60,parts=days>0?[[days,'days'],[hours,'hrs'],[minutes,'mins']]:[[hours,'hrs'],[minutes,'mins'],[seconds,'secs']],progress=remaining<=0?0:Math.min(100,remaining/(24*60*60*1000)*100);return{remaining,parts,progress,isNow:remaining<=0};}
function countdownDigits(model){return model.parts.map(([value,label])=>`<span><strong>${String(value).padStart(2,'0')}</strong><small>${label}</small></span>`).join('');}
function leaveCountdown(value,reason,assumption){if(!value)return `<section class="leave-countdown-card pending"><div class="leave-countdown-head"><div><div class="eyebrow">When to leave</div><h3>Leave time is being prepared</h3></div></div><p>Add your starting location so Wayfinder can calculate this journey.</p></section>`;const model=countdownModel(value),exact=`${clock(value,ORIGIN_ZONE)} · ${day(value,ORIGIN_ZONE)}`;return `<section class="leave-countdown-card ${model.isNow?'is-now':''}" data-countdown-target="${e(value)}" aria-label="${model.isNow?'Leave now':`Time remaining until ${exact}`}"><div class="leave-countdown-head"><div><div class="eyebrow">When to leave</div><h3>${model.isNow?'Leave now':`Leave by ${e(clock(value,ORIGIN_ZONE))}`}</h3></div><span class="countdown-mode">Trip estimate</span></div><div class="countdown-wheel" style="--countdown-progress:${model.progress}%"><div class="countdown-wheel-inner"><span class="countdown-kicker">${model.isNow?'Time to go':'You leave in'}</span><div class="countdown-digits">${countdownDigits(model)}</div></div><span class="countdown-car" aria-hidden="true">➤</span></div><p class="countdown-exact">${e(exact)} · Wayfinder will keep this time updated</p><details class="countdown-basis"><summary>How this was calculated</summary><p>${e(reason)}</p>${assumption?`<p>${e(assumption)}</p>`:''}</details></section>`;}
function updateLeaveCountdowns(){document.querySelectorAll('[data-countdown-target]').forEach(card=>{const model=countdownModel(card.dataset.countdownTarget);if(!model)return;card.style.setProperty('--countdown-progress',`${model.progress}%`);card.classList.toggle('is-now',model.isNow);const digits=card.querySelector('.countdown-digits');if(digits)digits.innerHTML=countdownDigits(model);const kicker=card.querySelector('.countdown-kicker');if(kicker)kicker.textContent=model.isNow?'Time to go':'You leave in';const heading=card.querySelector('h3');if(model.isNow&&heading)heading.textContent='Leave now';card.setAttribute('aria-label',model.isNow?'Leave now':`Time remaining until ${clock(card.dataset.countdownTarget,ORIGIN_ZONE)}`);});}
function fact(key,fallback='Not added yet'){return state.trip?.facts[key]?.value??fallback;}
function tag(text,cls=''){return `<span class="tag ${cls}">${e(text)}</span>`;}
function currentPlan(t=state.trip){return t?.plan&&!t.plan.stale?t.plan:null;}
function currentAction(t=state.trip){return t?.plan?t.actions.find(a=>a.plan_id===t.plan.id):null;}
function tripCommitments(t=state.trip){return Array.isArray(t?.commitments)?t.commitments:[];}
function tripImpacts(t=state.trip){if(Array.isArray(t?.impacts))return t.impacts;return tripCommitments(t).filter(c=>c.impact).map(c=>({commitment_id:c.id,...c.impact}));}
function affectedImpacts(t=state.trip){return tripImpacts(t).filter(i=>i.affected!==false&&!['safe','unaffected','not_affected','unchanged','no_change'].includes(String(i.status||'').toLowerCase()));}
function flightExperience(t=state.trip){const x=t?.flight_experience||{},check=x.check_in||{},pass=x.boarding_pass||check.boarding_pass||null,checked=check.checked_in===true||check.status==='checked_in'||x.checked_in===true||!!pass;return{...x,check_in:{...check,checked_in:checked},boarding_pass:pass,leave:x.leave_for_airport||x.departure_guidance||null,delay:x.delay||null,affected:x.affected||{}};}
function trainExperience(t=state.trip){const x=t?.train_experience||{},ticket=x.ticket||{},station=x.station_departure||x.station_access||x.departure_guidance||{},lastMile=x.last_mile||{},options=Array.isArray(lastMile)?lastMile:Array.isArray(lastMile.options)?lastMile.options:Array.isArray(x.last_mile_options)?x.last_mile_options:[],reference=ticket.booking_reference||ticket.reference||x.booking_reference||t?.facts?.['connection.booking_reference']?.value||null,departure=station.departure_at||x.departure_at||x.departure||t?.facts?.['connection.departure']?.value||null,route=x.route||t?.facts?.['connection.route']?.value||'Onward train';return{...x,route,departure,ticket:{...ticket,booking_reference:reference,booked:ticket.booked??Boolean(reference)},station,last_mile:{...(Array.isArray(lastMile)?{}:lastMile),options}};}
function placeExperience(id,t=state.trip){return (t?.place_experiences||[]).find(item=>item.commitment_id===id)||null;}
function sourceDocumentFor(item,t=state.trip){const id=typeof item==='string'?item:item?.source_document_id;return id?(t?.documents||[]).find(doc=>doc.id===id)||null:null;}
function sourceDocumentCard(itemOrId,title='Booking document'){const doc=sourceDocumentFor(itemOrId);if(!doc)return'';return `<section class="source-document-card"><span class="source-document-icon">▤</span><div><div class="eyebrow">${e(title)}</div><h3>${e(doc.name)}</h3><p>Saved with this itinerary · ${e(doc.pages?.length||1)} page${doc.pages?.length===1?'':'s'}</p></div><button class="button secondary" data-action="document" data-id="${e(doc.id)}">Open</button></section>`;}
function relatedDocumentCards(item,title='Booking document',t=state.trip){const docs=[],source=sourceDocumentFor(item,t);if(source)docs.push(source);if(/w circuit/i.test(String(item?.title||''))){for(const doc of t?.documents||[]){if(/w.?circuit|patagonia|torres.*paine|^program\b/i.test(doc.name)&&!docs.some(saved=>saved.id===doc.id))docs.push(doc);}}return docs.map((doc,index)=>`<section class="source-document-card"><span class="source-document-icon">▤</span><div><div class="eyebrow">${e(index? 'Original confirmation':title)}</div><h3>${e(doc.name)}</h3><p>Saved with this itinerary · ${e(doc.pages?.length||1)} page${doc.pages?.length===1?'':'s'}</p></div><button class="button secondary" data-action="document" data-id="${e(doc.id)}">Open</button></section>`).join('');}
function impactLabel(status){return({affected:'Affected',at_risk:'May be affected',missed:'No longer works',conflict:'Time conflict',needs_attention:'Needs attention',timing_unknown:'Timing needs review'})[String(status||'').toLowerCase()]||'Check this plan';}
function downstreamImpactText(item,impact){if(!impact)return'';const available=impact.available_at?new Date(impact.available_at):null,start=item.start?new Date(item.start):null;if(available&&start&&!Number.isNaN(available.getTime())&&!Number.isNaN(start.getTime())&&available>start){const minutes=Math.ceil((available-start)/60000),duration=minutes>=60?`${Math.floor(minutes/60)} hr${Math.floor(minutes/60)===1?'':'s'}${minutes%60?` ${minutes%60} min`:''}`:`${minutes} min`;return `Reachable ${duration} late · earliest ${clock(impact.available_at,DESTINATION_ZONE)}`;}return impact.suggested_action||impact.reason||'';}
function commitmentIcon(kind){return({meal:'♨',dining:'♨',restaurant:'♨',meeting:'●',work:'●',activity:'◇',tour:'◇',event:'☆',transport:'↗'})[String(kind||'').toLowerCase()]||'◇';}
function commitmentSource(value){const source=String(value||'').toLowerCase();if(['chat','voice','manual'].includes(source))return'Added by you';if(source==='document')return'From your trip documents';return value||'';}
function notifications(){if(!state.trip)return[];const t=state.trip,items=[],status=t.event?.status,p=currentPlan(t),chosen=currentAction(t);if(p?.result?.connection_missed&&!chosen)items.push({kind:'Action needed',title:'Your onward connection is no longer reachable',detail:'Recovery choices are ready. Pick one and keep moving.',urgent:true});else if(['cancelled','diverted','incident'].includes(status))items.push({kind:'Action needed',title:`Flight ${status}`,detail:'Wayfinder cannot complete this change automatically. Airline assistance is needed.',urgent:true});else if(status==='delayed'&&!p&&!chosen)items.push({kind:'Flight update',title:'Your flight is delayed',detail:'We are checking how the delay affects the rest of your trip.',urgent:true});const soon=(t.reminders||[]).filter(r=>{const ms=new Date(r.at).getTime()-Date.now();return r.due||(ms>=0&&ms<=24*60*60*1000);}).slice(0,1);for(const r of soon)items.push({kind:r.due?'Due':'Next 24 hours',title:r.title,detail:fmt(r.at),urgent:r.due});return items;}
function delayLabel(t){const p=currentPlan(t),scheduled=t?.facts?.['flight.arrival']?.value,estimated=t?.event?.estimated_arrival||t?.event?.arrival;let minutes=p?.result?.delay_minutes;if(typeof minutes!=='number'&&scheduled&&estimated)minutes=Math.max(0,Math.round((new Date(estimated)-new Date(scheduled))/60000));if(!t.event||typeof minutes!=='number')return null;return minutes>=60&&minutes%60===0?`${minutes/60} hr delay`:`${minutes} min delay`;}
function flightStatus(t){if(t.event){const mode=t.event.simulation?'Sample':'Live',status=t.event.status==='delayed'&&delayLabel(t)?delayLabel(t):t.event.status?String(t.event.status).replaceAll('_',' '):'updated';return{label:`${mode} · ${status}`,cls:['cancelled','diverted','incident','delayed'].includes(t.event.status)?'amber':'gray'};}if(t.trip.scenario==='heathrow-demo')return{label:'Sample itinerary',cls:'gray'};return{label:'Status not checked',cls:'gray'};}
function toast(text,error=false){const el=$('#toast');el.textContent=text;el.className=error?'error':'';el.style.display='block';clearTimeout(toast.timer);toast.timer=setTimeout(()=>el.style.display='none',6500);}
async function api(path,data){const r=await fetch(path,data===undefined?{}:{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(data)});let result;try{result=await r.json();}catch{throw Error('The server returned an unexpected response. Please retry.');}if(!r.ok)throw Error(result.error||'Request failed');return result;}
async function refresh(){state.trips=await api('/api/trips');if(state.trip){state.trip=await api('/api/trips/'+state.trip.trip.id);}render();}
async function selectTrip(id){state.trip=await api('/api/trips/'+id);state.page='trips';state.showAssistant=false;state.liveStatus=null;render();window.scrollTo({top:0,left:0,behavior:'auto'});startMonitoring();startSampleMonitor();}
function endpoint(action){return `/api/trips/${state.trip.trip.id}/${action}`;}

function render(){
  const t=state.trip;
  const inTrip=t&&state.page!=='welcome';
  const header=inTrip?`<button class="manage-back" data-action="manage-itineraries" aria-label="Back to itineraries">‹ <span>Itineraries</span></button><button class="header-mark" data-action="page" data-page="trips" aria-label="Open current trip">↗</button><div class="header-actions"><button class="icon-button notification-button" data-action="notifications-toggle" aria-label="Open notifications">♢${notifications().some(n=>n.urgent)?'<span class="notification-dot"></span>':''}</button><button class="icon-button" data-action="page" data-page="connections" aria-label="Open trip settings">⚙</button></div>`:`<button class="wordmark" data-action="manage-itineraries"><span class="brand-mark">↗</span><span>wayfinder</span></button><span class="manager-label">My itineraries</span>`;
  $('#app').innerHTML=`<div class="app-shell"><header class="mobile-header ${inTrip?'in-trip':'in-manager'}">${header}</header><main class="phone-main">${state.page==='welcome'?onboarding():state.page==='connections'?connections():t?tripView():emptyView()}</main>${t&&state.page==='trips'?bottomNav():''}${state.showAssistant&&t?`<div class="assistant-backdrop" data-action="assistant-toggle"></div>${assistant()}`:''}${state.showNotifications&&t?`<div class="assistant-backdrop" data-action="notifications-toggle"></div>${notificationPanel()}`:''}${state.showAddPlans&&t?`<div class="assistant-backdrop" data-action="add-plans-toggle"></div>${addPlansSheet()}`:''}${state.showFlight&&t?`<div class="assistant-backdrop" data-action="flight-toggle"></div>${flightSheet()}`:''}${state.showTrain&&t?`<div class="assistant-backdrop" data-action="train-toggle"></div>${trainSheet()}`:''}${state.showPlace&&t?`<div class="assistant-backdrop" data-action="place-close"></div>${placeSheet(state.showPlace)}`:''}</div>`;
  if(t&&state.page==='trips'){renderChat();}
  bindDrop();
  updateLeaveCountdowns();
  renderGooglePlaceMap();
}
function bottomNav(){return `<nav class="bottom-nav" aria-label="Primary"><button class="${state.page==='trips'&&state.tab==='overview'?'active':''}" data-action="mobile-tab" data-tab="overview"><span>⌂</span>Trip</button><button class="${state.page==='trips'&&state.tab==='recovery'?'active':''}" data-action="mobile-tab" data-tab="recovery"><span>↻</span>Recover</button><button class="ask-nav" data-action="assistant-toggle"><span>✦</span>Ask</button><button class="${state.page==='trips'&&state.tab==='documents'?'active':''}" data-action="mobile-tab" data-tab="documents"><span>▤</span>Docs</button><button class="${state.page==='trips'&&['essentials','activity'].includes(state.tab)?'active':''}" data-action="mobile-tab" data-tab="essentials"><span>•••</span>More</button></nav>`;}
function notificationPanel(){const items=notifications(),permission=typeof Notification==='undefined'?'unsupported':Notification.permission;return `<aside class="notification-panel" aria-label="Notifications"><div class="sheet-handle"></div><div class="notification-head"><div><div class="eyebrow">Only what needs you</div><h2>Trip alerts</h2></div><button class="close-sheet" data-action="notifications-toggle" aria-label="Close notifications">×</button></div><div class="notification-list">${items.length?items.map(n=>`<div class="notification-item ${n.urgent?'urgent':''}"><span class="notification-icon">${n.urgent?'!':'◷'}</span><div><div class="eyebrow">${e(n.kind)}</div><strong>${e(n.title)}</strong><p>${e(n.detail)}</p></div></div>`).join(''):'<div class="all-clear"><span>✓</span><strong>You’re all caught up</strong><p>No disruption or near-term deadline needs your attention.</p></div>'}</div><div class="notification-footer"><button class="button secondary" data-action="enable-notifications" ${permission==='granted'||permission==='unsupported'?'disabled':''}>${permission==='granted'?'Alerts enabled':permission==='unsupported'?'Alerts unavailable':'Enable trip alerts'}</button><p class="footnote">Alerts appear while Wayfinder is open.</p></div></aside>`;}
function notifyRecovery(){const urgent=notifications().find(n=>n.urgent),latest=state.trip?.notifications?.[0];if(!urgent||typeof Notification==='undefined'||Notification.permission!=='granted')return;const key=latest?.id||`${state.trip.trip.id}:${state.trip.trip.revision}`;if(localStorage.getItem('wayfinder-alert-'+key))return;localStorage.setItem('wayfinder-alert-'+key,'shown');new Notification('Wayfinder: decision needed',{body:urgent.title+'. '+urgent.detail});}
const wait=ms=>new Promise(resolve=>setTimeout(resolve,ms));
async function monitorTick(){if(state.monitoring||state.busy||state.asking||document.hidden||!state.trip)return;state.monitoring=true;try{const id=state.trip.trip.id,before=state.trip.trip.revision;let next=await api('/api/trips/'+id),flight=next.facts['flight.flight_id']?.value||'',sample=next.trip.scenario==='heathrow-demo';if(!sample&&flight&&state.health?.configuration?.flight_api!=='not_configured'&&Date.now()-state.lastLiveCheck>5*60*1000){state.lastLiveCheck=Date.now();if(!next.monitor?.enabled)await api(`/api/trips/${id}/monitor`,{enabled:true});await api(`/api/trips/${id}/check-flight`,{});next=await api('/api/trips/'+id);}if(state.trip?.trip.id===id&&next.trip.revision!==before){state.trip=next;render();notifyRecovery();}}catch(err){console.warn('Trip monitoring will retry',err.message);}finally{state.monitoring=false;}}
function startMonitoring(){clearInterval(startMonitoring.timer);startMonitoring.timer=setInterval(monitorTick,4000);setTimeout(monitorTick,500);}
async function startSampleMonitor(){
  const t=state.trip;
  if(!t||t.trip.scenario!=='heathrow-demo'||t.flight_statuses.some(s=>s.status==='delayed'))return;
  const id=t.trip.id;
  if(state.sampleMonitoringTripId===id)return;
  state.sampleMonitoringTripId=id;
  try{
    if(!t.monitor?.enabled)await api(`/api/trips/${id}/monitor`,{enabled:true});
    if(!t.flight_statuses.some(s=>['on_time','scheduled'].includes(s.status))){
      await api(`/api/trips/${id}/replay`,{minutes:0,cause:'weather',event_key:`${id}-sample-on-time`});
      state.trip=await api('/api/trips/'+id);
      render();
      toast('Itinerary created. Your flight and connections are on time.');
    }
    // Keep the initial on-time itinerary visible before the simulated provider update arrives.
    await wait(7000);
    if(state.trip?.trip.id!==id)return;
    await api(`/api/trips/${id}/replay`,{minutes:120,cause:'weather',event_key:`${id}-sample-delay`});
    state.trip=await api('/api/trips/'+id);
    render();
    notifyRecovery();
    toast('Flight delay detected. Your connections and plans were updated.');
  }catch(err){
    toast('The sample monitor could not finish. You can retry from Presenter controls.',true);
  }finally{
    if(state.sampleMonitoringTripId===id)state.sampleMonitoringTripId=null;
  }
}
function managerDate(value){const d=new Date(value);return Number.isNaN(d.getTime())?'Saved itinerary':`Created ${d.toLocaleDateString('en-US',{month:'short',day:'numeric',year:'numeric'})}`;}
function onboarding(){const trips=state.trips||[];return `<section class="onboarding itinerary-manager"><div class="onboarding-copy"><div class="eyebrow">Every trip, one place</div><h1>Where are you going?</h1><p>Create an itinerary from your inbox or documents, then return here whenever you need it.</p></div><section class="manager-section" aria-labelledby="new-itinerary-title"><div class="manager-section-head"><div><div class="eyebrow">Start a trip</div><h2 id="new-itinerary-title">New itinerary</h2></div></div><div class="onboarding-paths"><button class="onboarding-path primary-path" data-action="connect-email"><span class="path-icon">✉</span><div><small>Fastest</small><h3>Connect email</h3><p>Find booking confirmations automatically.</p></div><b aria-hidden="true">→</b></button><button class="onboarding-path" data-action="onboard-documents"><span class="path-icon">▤</span><div><small>Upload</small><h3>Add documents</h3><p>Build a trip from confirmations.</p></div><b aria-hidden="true">→</b></button></div></section><section class="manager-section saved-itineraries" aria-labelledby="saved-itineraries-title"><div class="manager-section-head"><div><div class="eyebrow">Continue planning</div><h2 id="saved-itineraries-title">Your itineraries</h2></div><span>${trips.length}</span></div><div class="itinerary-manager-list">${trips.length?trips.map(trip=>`<button class="itinerary-manager-row" data-action="select-trip" data-id="${e(trip.id)}"><span class="itinerary-manager-icon">${trip.scenario==='heathrow-demo'?'✈':'◇'}</span><span><strong>${e(trip.title)}</strong><small>${e(managerDate(trip.created))} · ${trip.scenario==='heathrow-demo'?'Sample trip':'Your trip'}</small></span><b>›</b></button>`).join(''):`<div class="manager-empty"><strong>No saved itineraries yet</strong><p>Connect email or add documents to create your first trip.</p></div>`}</div></section><div class="onboarding-trust"><span>✓ You review details before they are used</span><span>✓ No booking changes without approval</span></div></section>`;}
function emptyView(){return `<div class="empty"><div class="empty-symbol">⌁</div><div class="eyebrow">Your journey, connected</div><h1 class="serif" style="margin-top:15px">Less travel admin.<br>More peace of mind.</h1><p>Add your bookings once. Wayfinder watches the trip, explains what changed, and prepares choices when plans go wrong.</p><div class="row" style="justify-content:center"><button class="button" data-action="load-demo">Explore the sample trip ↗</button><button class="button secondary" data-action="new-trip">Create an itinerary</button></div><p class="footnote">Sample bookings and prices are fictional.</p><div class="empty-features"><div><h3>01 &nbsp; Add your trip</h3><p>Upload booking confirmations and travel documents.</p></div><div><h3>02 &nbsp; Stay informed</h3><p>Wayfinder watches changes and checks the impact on the whole journey.</p></div><div><h3>03 &nbsp; Choose and continue</h3><p>When a decision is needed, pick from options that fit your timing and spending limit.</p></div></div></div>`;}
function tripView(){const t=state.trip,sim=t.trip.scenario==='heathrow-demo',ready=t.documents?.length&&t.documents.every(d=>d.state==='reviewed');return `<section class="trip-heading"><div><div class="badge-line">${tag(sim?'SAMPLE TRIP':'MY TRIP',sim?'amber':'gray')}<span class="top-hint">Times shown in each booking’s local time</span></div><h1>${e(t.trip.title)}</h1><div class="trip-subline"><p>${sim?'Nov 6–10 · San Francisco to London':ready?'Your itinerary is ready and being monitored.':'Review your documents to connect this trip.'}</p><button class="document-upload-summary" data-action="upload-click" aria-label="Upload trip documents. ${t.document_count} of 15 uploaded">＋ Upload documents · ${t.document_count}/15</button></div></div></section>${state.tab==='overview'?liveBriefing():journey()}<nav class="tabs" aria-label="Itinerary sections">${[['overview','Itinerary'],['recovery','Recovery'],['documents','Documents'],['essentials','Travel details'],['activity','Activity']].map(([id,label])=>`<button class="tab ${state.tab===id?'active':''}" data-action="tab" data-tab="${id}">${label}</button>`).join('')}</nav><section id="tab-content">${({overview,documents,recovery,essentials,activity}[state.tab]||overview)()}</section><input class="hidden" type="file" id="file-input" accept=".txt,.pdf" multiple>`;}
function liveBriefing(){const t=state.trip,zone=tripDestinationZone(t),status=flightStatus(t),plan=currentPlan(t),action=currentAction(t),missed=!!plan?.result?.connection_missed&&!action,boarding=fact('flight.boarding_time',null),gate=fact('flight.gate','—'),arrival=t.event?.arrival||fact('flight.arrival',null);const headline=missed?'Your connection needs a decision':t.event?.status==='delayed'?`Flight update · arriving ${clock(arrival,zone)}`:`Flight ${fact('flight.flight_id','status')} · ${status.label.replace(/^Sample · /,'').replace(/^Live · /,'')}`;const detail=missed?'Options that protect your plans are ready.':boarding?`Board ${clock(boarding,ORIGIN_ZONE)} · Gate ${gate}`:'We are watching for airline updates';const mode=t.event?.simulation?'Demo':t.trip.scenario==='heathrow-demo'?'Sample':'Live';return `<section class="live-briefing ${missed||t.event?.status==='delayed'?'attention':''}" aria-label="Latest trip update"><span class="live-briefing-icon" aria-hidden="true">${missed?'!':'✈'}</span><div><strong>${e(headline)}</strong><small>${e(detail)}</small></div>${missed?'<button class="button" data-action="tab" data-tab="recovery">Choose option</button>':`<span class="journey-chip ${status.cls==='amber'?'attention':'live'}">${e(mode)}</span>`}</section>`;}
function journey(){const t=state.trip,sim=t.trip.scenario==='heathrow-demo',zone=tripDestinationZone(t),destination=tripDestinationName(t),status=flightStatus(t),boarding=fact('flight.boarding_time',null),departure=fact('flight.departure',null),arrival=t.event?.arrival||fact('flight.arrival',null),terminal=fact('flight.terminal','—'),gate=fact('flight.gate','—'),seat=fact('flight.seat','—');return `<div class="journey"><div class="row between"><div><span class="eyebrow">${e(fact('flight.flight_id','Flight'))}</span><div class="journey-status">${tag(status.label,status.cls)}</div></div><span class="journey-confirmation">Confirmation<br><strong>${e(fact('flight.booking_reference','Not provided'))}</strong></span></div><div class="route"><div><div class="airport">SFO</div><div class="city">San Francisco</div></div><div class="route-line">✈</div><div style="text-align:right"><div class="airport">${destination==='Santiago'?'SCL':'LHR'}</div><div class="city">${e(destination)}</div></div></div><div class="boarding-grid"><div><span>Boarding</span><strong>${e(clock(boarding,ORIGIN_ZONE))}</strong><small>${e(day(boarding,ORIGIN_ZONE))}</small></div><div><span>Terminal · gate</span><strong>${e(terminal)} · ${e(gate)}</strong><small>${e(departure?`Departs ${clock(departure,ORIGIN_ZONE)}`:'Not in documents')}</small></div><div><span>Seat</span><strong>${e(seat)}</strong><small>From booking</small></div><div><span>Arrival</span><strong>${e(clock(arrival,zone))}</strong><small>${e(day(arrival,zone))} · ${e(destination)}</small></div></div></div>`;}
function source(key){const f=state.trip.facts[key];return f?`<button class="source-link" data-action="document" data-id="${f.document_id}">↳ ${e(f.document_name)}</button>`:'';}
function itineraryItems(t=state.trip){const items=[],destZone=tripDestinationZone(t),destName=tripDestinationName(t),train=t.train_experience||{},original=train.original_connection||{},recovery=train.recovery_connection||null,connectionMissed=original.state==='missed'||!!currentPlan(t)?.result?.connection_missed;if(t.facts['flight.flight_id'])items.push({id:'booking-flight',kind:'flight',icon:'✈',title:fact('flight.flight_id','Flight'),detail:fact('flight.route','Flight booking'),start:fact('flight.departure',null),end:fact('flight.arrival',null),zone:ORIGIN_ZONE,meta:`${fact('flight.boarding_time',null)?`Boarding ${clock(fact('flight.boarding_time',null),ORIGIN_ZONE)} · `:''}Arrive ${clock(t.event?.arrival||fact('flight.arrival',null),destZone)} ${destName}`,sourceKey:'flight.departure'});if(t.facts['connection.departure'])items.push({id:'booking-connection',kind:'transport',icon:'↗',title:'Onward connection',detail:fact('connection.route','Onward booking'),start:original.departure_at||fact('connection.departure',null),zone:destZone,connectionMissed,meta:connectionMissed?`Leaves before your flight arrives at ${clock(t.event?.arrival||fact('flight.arrival',null),destZone)}`:`Confirmation ${fact('connection.booking_reference','Not provided')}`,sourceKey:'connection.departure'});if(recovery?.selected){const mode=String(recovery.mode||'alternative'),isTrain=mode==='train';items.push({id:'booking-recovery-connection',kind:'transport',icon:isTrain?'▰':'↗',title:isTrain?'Replacement train':`${mode[0]?.toUpperCase()||''}${mode.slice(1)} onward`,detail:'Selected recovery option',start:recovery.departure_at||t.event?.arrival||null,zone:destZone,replacement:true,meta:[`Selected recovery`,recovery.cost!==null&&recovery.cost!==undefined?`$${recovery.cost} extra`:'',recovery.hotel_arrival?`Arrive ${clock(recovery.hotel_arrival,destZone)}`:''].filter(Boolean).join(' · ')});}if(t.facts['hotel.hotel_name'])items.push({id:'booking-hotel',kind:'hotel',icon:'⌂',title:fact('hotel.hotel_name','Hotel'),detail:'Check-in deadline',start:fact('hotel.check_in_deadline',null),end:fact('hotel.check_out',null),zone:destZone,meta:`Confirmation ${fact('hotel.booking_reference','Not provided')}`,sourceKey:'hotel.check_in_deadline'});for(const c of tripCommitments(t)){const kind=c.kind||c.type,zone=commitmentZone(c,t),crossZone=kind==='transport'&&/\s+to\s+/i.test(String(c.location||''));items.push({...c,kind,icon:commitmentIcon(kind),personal:true,zone,detail:c.location||String(kind||'Personal plan').replaceAll('_',' '),meta:[c.end&&!crossZone?`Until ${clock(c.end,zone)}`:'',c.flexibility?String(c.flexibility).replaceAll('_',' '):''].filter(Boolean).join(' · ')});}const time=value=>{const result=value?new Date(value).getTime():NaN;return Number.isFinite(result)?result:Infinity;};return items.sort((a,b)=>time(a.start)-time(b.start));}
function itineraryDayKey(item){if(!item.start)return'unscheduled';const d=new Date(item.start);if(Number.isNaN(d.getTime()))return'unscheduled';const parts=new Intl.DateTimeFormat('en-CA',{timeZone:item.zone||DESTINATION_ZONE,year:'numeric',month:'2-digit',day:'2-digit'}).formatToParts(d);const value=type=>parts.find(p=>p.type===type)?.value||'';return`${value('year')}-${value('month')}-${value('day')}`;}
function itineraryDayLabel(item){if(!item.start)return'Date to be confirmed';const d=new Date(item.start);if(Number.isNaN(d.getTime()))return'Date to be confirmed';return d.toLocaleDateString('en-US',{timeZone:item.zone||DESTINATION_ZONE,weekday:'long',month:'long',day:'numeric'});}
function itineraryGroups(items){const groups=[];for(const item of items){const key=itineraryDayKey(item);let group=groups.find(g=>g.key===key);if(!group){group={key,label:itineraryDayLabel(item),items:[]};groups.push(group);}group.items.push(item);}return groups;}
function nextItineraryId(items){const now=Date.now(),upcoming=items.find(item=>{const time=item.start?new Date(item.start).getTime():NaN;return Number.isFinite(time)&&time>=now;});return upcoming?.id||null;}
function itineraryItemStatus(item,t,affected,isNext){if(item.connectionMissed)return{label:'Missed',cls:'danger'};if(item.replacement)return{label:'Selected',cls:'live'};if(affected){const severe=['affected','missed','conflict'].includes(String(affected.status||'').toLowerCase());return{label:impactLabel(affected.status),cls:severe?'danger':'attention'};}if(item.kind==='flight'){const status=flightStatus(t);return{label:status.label.replace(/^Sample · /,'').replace(/^Live · /,''),cls:status.cls==='amber'?'attention':'live'};}if(isNext)return{label:'Up next',cls:'next'};return{label:item.personal?'Planned':'Confirmed',cls:'calm'};}
function itineraryRow(item,t=state.trip,isNext=false){const impact=tripImpacts(t).find(i=>i.commitment_id===item.id),affected=impact&&impact.affected!==false&&!['safe','unaffected','not_affected','unchanged','no_change'].includes(String(impact.status||'').toLowerCase())?impact:null,status=itineraryItemStatus(item,t,affected,isNext),flight=item.kind==='flight',train=item.id==='booking-connection'||item.replacement,place=item.personal&&!!placeExperience(item.id,t),documentItem=item.personal&&!!sourceDocumentFor(item,t),interactive=flight||train||place||documentItem,action=flight?'flight-toggle':train?'train-toggle':'place-toggle',disrupted=!!item.connectionMissed,recovered=!!item.replacement,severe=disrupted||['affected','missed','conflict'].includes(String(affected?.status||'').toLowerCase()),impactText=downstreamImpactText(item,affected);return `<article class="timeline-item journey-stop ${interactive?'interactive-journey':''} ${flight?'interactive-flight':''} ${train?'interactive-train':''} ${place?'interactive-place':''} ${item.personal?'personal-plan':''} ${affected?'affected-plan':''} ${severe?'disrupted-plan':''} ${recovered?'recovery-plan':''} ${isNext?'next-plan':''}" ${interactive?`data-action="${action}" ${!flight&&!train?`data-id="${e(item.id)}"`:''} role="button" tabindex="0"`:''} aria-label="${e(item.title||'Personal plan')}, ${e(status.label)}${impactText?`, ${e(impactText)}`:''}${interactive?', open journey details':''}"><div class="time">${e(clock(item.start,item.zone))}</div><div class="event-icon ${severe?'danger':recovered?'recovery':affected?'amber':isNext?'next':''}" aria-hidden="true">${e(item.icon||'◇')}</div><div class="timeline-content"><div class="timeline-title"><h3>${e(item.title||'Personal plan')}</h3><span class="journey-chip ${e(status.cls)}">${e(status.label)}</span>${interactive?'<span class="row-chevron" aria-hidden="true">›</span>':''}</div><p>${e(item.detail||'')}</p>${item.meta?`<div class="timeline-meta">${e(item.meta)}</div>`:''}${impactText?`<div class="timeline-impact">${e(impactText)}</div>`:''}${item.sourceKey?source(item.sourceKey):item.source?`<div class="source-caption">${e(commitmentSource(item.source))}</div>`:''}${item.personal?`<button class="remove-plan" data-action="remove-plan" data-id="${e(item.id)}" aria-label="Remove ${e(item.title||'plan')}">Remove</button>`:''}</div></article>`;}
function itineraryTimeline(items,t=state.trip){const nextId=nextItineraryId(items);return `<div class="itinerary-days">${itineraryGroups(items).map(group=>`<section class="journey-day" aria-labelledby="day-${e(group.key)}"><header class="journey-day-header" id="day-${e(group.key)}"><span>${e(group.label)}</span><small>${group.items.length} ${group.items.length===1?'plan':'plans'}</small></header><div class="journey-day-items">${group.items.map(item=>itineraryRow(item,t,item.id===nextId)).join('')}</div></section>`).join('')}</div>`;}
function impactList(t=state.trip,compact=false){const items=affectedImpacts(t),zone=tripDestinationZone(t);if(!items.length)return'';return `<div class="impact-list ${compact?'compact':''}">${items.map(i=>{const c=tripCommitments(t).find(x=>x.id===i.commitment_id),available=i.available_at?`Available from ${clock(i.available_at,zone)}`:'';return `<div class="impact-item"><span>${commitmentIcon(c?.kind||c?.type)}</span><div><strong>${e(c?.title||'Personal plan')} · ${e(impactLabel(i.status))}</strong>${i.reason?`<p>${e(i.reason)}</p>`:''}${i.suggested_action||available?`<small>${e([i.suggested_action,available].filter(Boolean).join(' · '))}</small>`:''}</div></div>`;}).join('')}</div>`;}
function impactCard(t=state.trip){const items=affectedImpacts(t);if(!items.length)return'';return `<div class="card impact-card"><div class="eyebrow">Also on your schedule</div><h3>${items.length===1?'One personal plan may need attention':`${items.length} personal plans may need attention`}</h3>${impactList(t)}</div>`;}
function appliedRecovery(t,chosen,zone){const choice=chosen?.result?.option;if(!choice)return'';const original=t.train_experience?.original_connection,mode=String(choice.mode||'alternative'),label=mode==='train'?'Later train':mode==='taxi'?'Direct taxi':mode[0].toUpperCase()+mode.slice(1);return `<section class="applied-recovery" aria-label="Itinerary updated"><div class="applied-recovery-head"><span>✓</span><div><div class="eyebrow">Itinerary updated</div><h2>${e(label)} is now in your trip</h2><p>Wayfinder applied your choice and recalculated the plans that follow it.</p></div></div><div class="change-grid"><div><small>Original plan</small><strong>${e(original?.departure_at?clock(original.departure_at,zone):'Earlier connection')}</strong><span>Marked missed</span></div><div><small>New departure</small><strong>${e(clock(choice.departure,zone))}</strong><span>${e(label)} · selected</span></div><div><small>Arrive at hotel</small><strong>${e(clock(choice.hotel_arrival,zone))}</strong><span>Still before check-in</span></div><div><small>Added cost</small><strong>$${e(choice.cost)}</strong><span>Within your limit</span></div></div><div class="applied-recovery-foot"><span>✓ Your itinerary and reminders now use this option</span><button class="button ghost" data-action="tab" data-tab="activity">See the update history →</button></div></section>`;}
function overview(){const t=state.trip,zone=tripDestinationZone(t),destination=tripDestinationName(t),p=currentPlan(t),chosen=currentAction(t),missed=!!p?.result?.connection_missed&&!chosen,items=itineraryItems(t),disrupted=t.event&&!['on_time','scheduled','landed'].includes(t.event.status);return `${t.conflicts.length?`<div class="alert danger"><span>⚠</span><div><strong>Some trip details need attention</strong><p>Open Documents and check the highlighted information.</p></div></div>`:''}${chosen?appliedRecovery(t,chosen,zone):disrupted?`<div class="alert ${missed?'danger':''}"><span>!</span><div><strong>${missed?'Your connection needs attention':'Your onward connection is tight but still possible'}</strong><p>${t.event.simulation?'Demo update':'Latest update'}: ${e(destination)} arrival moved to ${e(fmt(t.event.arrival,{},zone))}. ${missed?'Your original connection is no longer reachable.':'Wayfinder checked every downstream plan.'}</p>${impactList(t,true)}${missed?'<button class="button ghost" data-action="tab" data-tab="recovery">Choose how to continue →</button>':''}</div></div>`:''}<div class="card itinerary-card"><div class="card-head"><div><div class="eyebrow">Your full itinerary</div><h2 class="serif">Bookings and plans</h2></div><button class="button secondary add-plan-button" data-action="add-plans-toggle">＋ Add plans</button></div>${items.length?itineraryTimeline(items,t):'<div class="empty-itinerary"><strong>No plans yet</strong><p>Add a reservation or tell Wayfinder what you plan to do.</p></div>'}</div><p class="footnote" style="margin:16px 3px">${t.trip.scenario==='heathrow-demo'?'This sample does not change any real booking.':'Wayfinder is watching this trip while the app is open.'}</p>`;}
function documents(){const t=state.trip;return `<div class="card"><div class="card-head"><div><div class="eyebrow">${t.document_count} of 15 added</div><h2 class="serif">Travel documents</h2></div></div><div class="upload-zone" id="drop-zone"><div style="font-size:25px;color:var(--teal)">↥</div><strong>Add booking confirmations and travel documents</strong><p>PDF or TXT · up to 10 MB each</p><button class="button secondary" data-action="upload-click">Choose files</button><p class="footnote">Scanned documents are not supported yet.</p></div>${state.uploading?'<p class="loading">Adding your trip details…</p>':''}${t.documents.length?t.documents.map(d=>`<div class="doc-row"><span class="event-icon">▤</span><div class="doc-details"><div class="doc-name">${e(d.name)}</div><div class="small">${e(d.kind)} · ${Object.keys(d.fields).length} trip detail${Object.keys(d.fields).length===1?'':'s'} found</div></div>${tag(d.state==='reviewed'?'Ready':'Check details',d.state==='reviewed'?'':'amber')}<button class="button ghost" data-action="document" data-id="${d.id}">${d.state==='reviewed'?'View':'Check'} →</button></div>`).join(''):'<p class="small">Add a booking confirmation to build your itinerary.</p>'}<div class="progress"><div style="width:${t.document_count/15*100}%"></div></div><p class="footnote">Check the details we found before Wayfinder uses them.</p></div>`;}
function recovery(){const t=state.trip,p=currentPlan(t),historical=t.plan,action=currentAction(t),result=p?.result,flight=e(fact('flight.flight_id','your flight')),monitorLabel=t.trip.scenario==='heathrow-demo'?'Sample monitoring':'Trip monitoring',last=t.monitor?.last_checked?`Last checked ${clock(t.monitor.last_checked)}`:'Watching for changes';if(action){const o=action.result.option;return `<div class="card recovery-complete"><span class="completion-mark">✓</span><div class="eyebrow">Choice saved</div><h2>You’re set to continue</h2><p>${e(o.mode)} leaves at ${e(clock(o.departure))} and gets you to the hotel at ${e(clock(o.hotel_arrival))}.</p><button class="button secondary" data-action="tab" data-tab="activity">View trip updates</button></div>${impactCard(t)}${demoControls(t)}`;}const monitor=`<div class="monitor-strip"><span class="monitor-pulse"></span><div><strong>We’re watching ${flight}</strong><small>${e(last)} · We’ll alert you only when you need to decide.</small></div>${tag(monitorLabel,'gray')}</div>`;if(!p)return `${monitor}<div class="card calm-state"><span class="completion-mark">✓</span><h2>${t.event?.status==='delayed'?'We’re checking the rest of your trip':'Nothing needs your attention'}</h2><p>${t.event?.status==='delayed'?'Wayfinder is checking bookings, personal plans, your spending limit, and relevant policies.':'Keep traveling. If something changes, Wayfinder will prepare the next steps.'}</p></div>${impactCard(t)}${historical?.stale&&!action?'<p class="footnote">Previous choices expired after the trip changed. New choices will appear if action is needed.</p>':''}${demoControls(t)}`;const feasible=result.options.filter(o=>o.feasible),rejected=result.options.filter(o=>!o.feasible);return `${monitor}${impactCard(t)}<div class="card recovery-decision"><div class="card-head"><div><div class="eyebrow">Decision needed</div><h2 class="serif">Choose how to continue</h2></div>${tag('Within $'+t.trip.budget+' limit','gray')}</div><p>Your original train is no longer reachable. Wayfinder checked arrival times, hotel check-in, personal plans, extra cost, and your saved preferences.</p>${result.status==='needs_manual_assistance'?'<div class="alert danger"><div><strong>These choices do not fit your trip</strong><p>Airline assistance or another route is needed.</p></div></div>':feasible.map((o,i)=>option(o,p,i)).join('')}${rejected.length?`<details class="excluded-options"><summary>Why other routes were excluded</summary>${rejected.map(o=>`<p><strong>${e(o.mode)}</strong> — ${e(o.rejection_reasons.join(', '))}</p>`).join('')}</details>`:''}<p class="footnote">Prices and availability are part of this sample. No booking changes until you confirm a choice.</p></div><div class="card coverage-card"><div class="eyebrow">Your card benefits</div><h3>Possible coverage to review</h3><p>${e(result.benefit_assessment.note)}</p><button class="button ghost" data-action="ask-suggestion" data-question="Could I be reimbursed, and what should I keep for a claim?">Ask about possible reimbursement →</button></div>${demoControls(t)}`;}
function option(o,p,index){const rec=o.id===p.result.recommended_option,label=String.fromCharCode(65+index);return `<div class="option ${rec?'recommended':''}"><div class="option-top"><div><div class="row" style="gap:6px;margin-bottom:8px">${tag(rec?'Recommended':`Option ${label}`)}</div><h3 style="margin:0">${o.mode==='train'?'Later train':o.mode==='taxi'?'Direct taxi':'Later bus'}</h3></div><div class="price">$${o.cost}<small>extra cost</small></div></div><p>Leaves ${e(clock(o.departure))} → hotel ${e(clock(o.hotel_arrival))}</p><button class="button ${rec?'':'secondary'}" data-action="approve" data-option="${o.id}">Choose option ${label} →</button></div>`;}
function demoControls(t){if(t.trip.scenario!=='heathrow-demo')return'';return `<details class="demo-tools"><summary>Presenter controls</summary><p>This control sends the same provider-style update that automatic monitoring receives. The traveler does not enter a delay.</p><button class="button secondary" data-action="demo-disruption" ${state.busy?'disabled':''}>${state.busy?'Updating trip…':'Run automatic disruption'}</button></details>`;}
function essentials(){const t=state.trip;return `<div class="card"><div class="card-head"><div><div class="eyebrow">Travel preferences</div><h2 class="serif">How Wayfinder should help</h2></div><button class="button ghost" data-action="budget-edit">Edit</button></div><div class="status-row"><span>Maximum extra spend during disruption</span><strong>$${t.trip.budget} USD</strong></div><p class="footnote">Recovery choices stay within this limit unless no workable option exists.</p></div><div class="card"><h2 class="serif">Important trip details</h2><div class="status-row"><span>Passport expiry</span><strong>${e(fact('passport.expiry_date'))}</strong></div><p class="footnote">Check entry requirements separately before travel.</p>${source('passport.expiry_date')}<div class="status-row"><span>${e(fact('rewards.program','Rewards program'))}</span><strong>${e(fact('rewards.balance','—'))} ${e(fact('rewards.unit',''))}</strong></div><p class="footnote">Balance from your latest document, dated ${e(fact('rewards.as_of'))}.</p>${source('rewards.balance')}<div class="status-row"><span>Travel benefit</span><strong style="max-width:55%;text-align:right;font-size:11px">${e(fact('benefit.policy_name'))}</strong></div>${source('benefit.policy_name')}</div><div class="card"><div class="card-head"><h2 class="serif">Coming up</h2>${tag('Wayfinder reminders','gray')}</div>${(t.reminders||[]).map(r=>`<div class="status-row"><div>${e(r.title)}</div><div style="text-align:right">${e(fmt(r.at))}<div class="footnote">${r.due?'Due or past':'Upcoming'}</div></div></div>`).join('')}<p class="footnote" style="margin-top:15px">These reminders appear in Wayfinder while the app is open.</p><button class="button secondary activity-link" data-action="tab" data-tab="activity">View trip updates →</button></div>`;}
function activity(){const t=state.trip;return `<div class="card"><div class="eyebrow">Trip history</div><h2 class="serif">What changed</h2>${t.actions.map(a=>`<div class="activity"><span class="completion-dot">✓</span><div style="flex:1"><strong>Recovery choice saved</strong><p>${e(a.result.option?.mode||a.option_id)} · arrive ${e(clock(a.result.option?.hotel_arrival))}. No booking was made.</p></div><span class="activity-time">${e(clock(a.created))}</span></div>`).join('')}${(t.notifications||[]).map(n=>`<div class="activity"><span class="dot" style="margin-top:5px"></span><div style="flex:1"><strong>${e(n.title)}</strong><p>${e(n.detail)}</p></div><span class="activity-time">${e(clock(n.created))}</span></div>`).join('')}${!t.actions.length&&!t.notifications?.length?'<div class="all-clear"><span>✓</span><strong>No changes yet</strong><p>Wayfinder will keep this timeline up to date.</p></div>':''}</div>`;}
function speechSupported(){return typeof window!=='undefined'&&('SpeechRecognition' in window||'webkitSpeechRecognition' in window);}
function addPlansSheet(){const examples=['Dinner on Nov 7 from 8:30 PM to 10 PM at Dishoom','British Museum on Nov 8 from 10 AM to 12 PM at Great Russell Street','Client meeting on Nov 9 from 4 PM to 5 PM at King’s Cross'];return `<aside class="add-plans-sheet" aria-label="Add plans"><div class="sheet-handle"></div><div class="add-plans-head"><div><div class="eyebrow">Your time matters too</div><h2>Add plans</h2><p>Tell Wayfinder about meals, meetings, tours, or anything else you do not want a disruption to derail.</p></div><button class="close-sheet" data-action="add-plans-toggle" aria-label="Close add plans">×</button></div><form id="add-plan-form" class="add-plan-form"><label for="plan-text">What are you planning?</label><div class="plan-compose"><textarea id="plan-text" name="text" maxlength="1000" required placeholder="Dinner on Nov 7 from 8:30 PM to 10 PM at Dishoom…">${e(state.planDraft)}</textarea>${speechSupported()?`<button type="button" class="voice-button ${state.listening?'listening':''}" data-action="voice-plan" aria-label="${state.listening?'Stop listening':'Add plan by voice'}"><span>${state.listening?'■':'●'}</span>${state.listening?'Listening…':'Speak'}</button>`:''}</div><div class="plan-examples"><span>Try saying</span>${examples.map(x=>`<button type="button" data-action="plan-example" data-text="${e(x)}">${e(x)}</button>`).join('')}</div><button class="button save-plan" type="submit" ${state.busy?'disabled':''}>${state.busy?'Adding plan…':'Add to my itinerary'}</button><p class="footnote">Include a date, start and end time, and place. You can remove the plan later.</p></form></aside>`;}
