async function getMapsConfig(){if(state.mapsConfig)return state.mapsConfig;if(mapsConfigLoader)return mapsConfigLoader;mapsConfigLoader=api('/api/maps-config').then(config=>state.mapsConfig=config&&config.enabled&&config.browser_api_key?config:{enabled:false,browser_api_key:''}).catch(()=>state.mapsConfig={enabled:false,browser_api_key:''});return mapsConfigLoader;}
function googleMapsBrowserKey(){return state.mapsConfig?.enabled?state.mapsConfig.browser_api_key||'':'';}
function loadGoogleMaps(){const key=googleMapsBrowserKey();if(!key)return Promise.reject(Error('The interactive map is not configured.'));if(window.google?.maps)return Promise.resolve(window.google.maps);if(googleMapsLoader)return googleMapsLoader;googleMapsLoader=new Promise((resolve,reject)=>{const callback=`wayfinderGoogleMapsReady_${Date.now()}`;const cleanup=()=>{try{delete window[callback];}catch{window[callback]=undefined;}};const script=document.createElement('script');window[callback]=()=>{cleanup();window.google?.maps?resolve(window.google.maps):reject(Error('Google Maps did not initialize.'));};script.src=`https://maps.googleapis.com/maps/api/js?key=${encodeURIComponent(key)}&v=weekly&loading=async&callback=${encodeURIComponent(callback)}`;script.async=true;script.defer=true;script.referrerPolicy='strict-origin-when-cross-origin';script.onerror=()=>{cleanup();googleMapsLoader=null;reject(Error('Google Maps could not load.'));};document.head.appendChild(script);});return googleMapsLoader;}
function placeMap(guide,route){if(googleMapsBrowserKey()){const label=route?`Live route from your current location to ${guide.destination.name}`:`Destination preview for ${guide.destination.name}`;return `<div class="place-map google-map-shell ${route?'live-google-map':''}" aria-label="${e(label)}"><div id="place-google-map" class="google-map-canvas" role="application" aria-label="Interactive Google map. ${e(label)}"></div><div class="google-map-placeholder"><span>⌖</span><strong>${e(guide.destination.name)}</strong><small>${route?'Loading your live route…':'Destination preview'}</small></div><div class="map-caption">${route?`Your location → ${e(guide.destination.name)}`:`${e(guide.destination.name)} · ${e(guide.destination.address)}`}</div><div class="map-key"><span>${route?'Google Maps route':'Destination'}</span><span>${route?'Updated now':'Location preview'}</span></div></div>`;}if(route){const model=liveMapModel(route);return `<div class="place-map live-google-map" role="img" aria-label="Live route preview from your current location to ${e(guide.destination.name)}"><svg viewBox="0 0 100 100" aria-hidden="true"><path class="map-grid" d="M0 22H100M0 44H100M0 66H100M0 88H100M22 0V100M44 0V100M66 0V100M88 0V100"/><path class="map-live-route" d="${model.path}"/><circle class="map-origin live" cx="${model.from.x}" cy="${model.from.y}" r="4"/><circle class="map-pin-ring" cx="${model.to.x}" cy="${model.to.y}" r="6"/><circle class="map-pin" cx="${model.to.x}" cy="${model.to.y}" r="3.2"/></svg><span class="map-origin-label" style="left:${model.from.x}%;top:${model.from.y}%">You</span><span class="map-destination-label" style="left:${model.to.x}%;top:${model.to.y}%">Plan</span><div class="map-caption">Your location → ${e(guide.destination.name)}</div><div class="map-key"><span>Route preview</span><span>Updated now</span></div></div>`;}const to=mapPosition(guide.destination);return `<div class="place-map neutral-place-map" role="img" aria-label="Destination preview for ${e(guide.destination.name)}"><svg viewBox="0 0 100 100" aria-hidden="true"><path class="map-river" d="M-5 66 C13 55 23 73 38 62 S64 54 108 67"/><path class="map-road" d="M4 28 C28 37 48 22 97 33"/><path class="map-road minor" d="M17 91 C32 62 57 45 83 12"/><circle class="map-pin-ring" cx="${to.x}" cy="${to.y}" r="6"/><circle class="map-pin" cx="${to.x}" cy="${to.y}" r="3.2"/></svg><span class="map-destination-label" style="left:${to.x}%;top:${to.y}%">Plan</span><div class="map-caption">${e(guide.destination.name)} · ${e(guide.destination.address)}</div><div class="map-key"><span>Destination preview</span><span>Use your location for a live route</span></div></div>`;}
async function renderGooglePlaceMap(){const placeId=state.showPlace;if(!placeId)return;if(!state.mapsConfig){await getMapsConfig();if(state.showPlace===placeId)render();return;}const canvas=$('#place-google-map');if(!canvas||!googleMapsBrowserKey())return;const guide=placeExperience(placeId),route=state.liveRoute;if(!guide)return;try{const maps=await loadGoogleMaps();if(state.showPlace!==placeId)return;const current=$('#place-google-map');if(!current)return;const destination={lat:Number(route?.destination?.lat??guide.destination.lat),lng:Number(route?.destination?.lng??guide.destination.lng)};placeGoogleMap=new maps.Map(current,{center:destination,zoom:14,disableDefaultUI:true,zoomControl:true,gestureHandling:'cooperative',clickableIcons:false,mapTypeControl:false,streetViewControl:false,fullscreenControl:false});new maps.Marker({map:placeGoogleMap,position:destination,title:guide.destination.name,icon:{path:maps.SymbolPath.CIRCLE,scale:8,fillColor:'#d97834',fillOpacity:1,strokeColor:'#ffffff',strokeWeight:3}});if(route){let points=[];try{points=decodePolyline(route.encoded_polyline||'');}catch{}if(points.length<2)points=[route.origin,destination];new maps.Polyline({map:placeGoogleMap,path:points,strokeColor:'#157266',strokeOpacity:1,strokeWeight:5});new maps.Marker({map:placeGoogleMap,position:route.origin,title:'Your current location',icon:{path:maps.SymbolPath.CIRCLE,scale:7,fillColor:'#2177d1',fillOpacity:1,strokeColor:'#ffffff',strokeWeight:3}});const bounds=new maps.LatLngBounds();points.forEach(point=>bounds.extend(point));bounds.extend(destination);placeGoogleMap.fitBounds(bounds,44);}current.classList.add('ready');current.setAttribute('aria-label',`${route?'Live route':'Destination'} map loaded with Google Maps`);current.parentElement?.querySelector('.google-map-placeholder')?.classList.add('hidden');}catch(err){const current=$('#place-google-map');if(current)current.setAttribute('aria-label',`Map unavailable: ${err.message}`);console.warn('Interactive map fallback remains active',err.message);}}
function placeModeOption(mode){const zone=tripDestinationZone(),icon=({walk:'Walk',transit:'Transit',taxi:'Taxi'})[mode.id]||mode.label,arrival=mode.arrive_by?clock(mode.arrive_by,zone):'',leave=mode.leave_at?clock(mode.leave_at,zone):'';return `<button class="place-mode ${mode.recommended?'recommended':''}" data-action="place-mode" data-mode="${e(mode.label)}"><span><strong>${e(icon)}</strong>${mode.recommended?'<small>Best fit</small>':''}</span><b>${e(mode.duration_minutes)} min</b><p>${leave?`Leave ${e(leave)} · `:''}${arrival?`arrive ${e(arrival)} · `:''}${e(money(mode.cost))}</p><em>Discuss →</em></button>`;}
function liveDistance(meters){return meters<1000?`${Math.round(meters)} m`:`${(meters/1000).toFixed(1)} km`;}
function liveDuration(seconds){const minutes=Math.max(1,Math.round(seconds/60));return minutes<60?`${minutes} min`:`${Math.floor(minutes/60)} hr ${minutes%60} min`;}
function liveRouteCard(guide){const route=state.liveRoute,mapsReady=state.health?.configuration?.google_routes==='configured',defaultMode=(guide.recommended_mode==='walk'?'walk':guide.recommended_mode==='transit'?'transit':'drive');if(route)return `<section class="live-route-card"><div class="live-route-head"><div><div class="eyebrow">${state.routeError?'Last successful route':'Live from your location'}</div><h3>${e(liveDuration(route.duration_seconds))} away</h3><p>${e(liveDistance(route.distance_meters))} · ${e(route.mode==='drive'?'Driving with current traffic':route.mode==='walk'?'Walking':'Public transit')}</p></div><span>Google</span></div><div class="live-route-modes">${[['walk','Walk'],['transit','Transit'],['drive','Drive']].map(([id,label])=>`<button class="${route.mode===id?'active':''}" data-action="live-place-mode" data-mode="${id}" ${state.locating?'disabled':''}>${label}</button>`).join('')}</div><button class="refresh-live-route" data-action="live-place-route" data-mode="${e(route.mode)}" ${state.locating?'disabled':''}>↻ ${state.locating?'Updating…':'Update from my location'}</button>${state.routeError?`<p class="live-route-error">Could not refresh: ${e(state.routeError)} Showing the last successful route.</p>`:''}</section>`;return `<section class="live-route-card"><div class="live-route-head"><div><div class="eyebrow">From where you are now</div><h3>See live time and distance</h3><p>${mapsReady?'Your location is used for this route only.':'Live directions are unavailable right now.'}</p></div><span>Google</span></div><button class="button live-route-button" data-action="live-place-route" data-mode="${defaultMode}" ${state.locating||!mapsReady?'disabled':''}>${state.locating?'Finding your route…':'Use my current location'}</button>${state.routeError?`<p class="live-route-error">${e(state.routeError)}</p>`:''}</section>`;}
function placeSheet(id){const guide=placeExperience(id),commitment=tripCommitments().find(item=>item.id===id);if(!commitment)return'';const recommended=guide?(guide.modes.find(mode=>mode.recommended)||guide.modes[0]):null,route=state.liveRoute,zone=commitmentZone(commitment),destination=guide?.destination;return `<aside class="place-sheet" aria-label="Trip details for ${e(commitment.title)}"><div class="sheet-handle"></div><header class="place-sheet-head"><div><div class="eyebrow">Your plan · ${e(clock(commitment.start,zone))}</div><h2>${e(commitment.title)}</h2><p>${e(destination?.address||commitment.location)}</p></div><button class="close-sheet" data-action="place-close" aria-label="Close trip details">×</button></header><div class="place-sheet-body">${guide?`${placeMap(guide,route)}${liveRouteCard(guide)}<section class="place-next-step"><div><div class="eyebrow">${route?'Current route':'Recommended'}</div><h3>${route?`${e(liveDuration(route.duration_seconds))} from you`:`Leave by ${e(clock(recommended.leave_at,zone))}`}</h3><p>${route?`${e(route.mode==='drive'?'Drive':route.mode==='walk'?'Walk':'Public transit')} to ${e(destination.name)}`:`${e(recommended.label)} from ${e(guide.origin.name)} · about ${e(recommended.duration_minutes)} minutes`}</p></div><span>${route?e(liveDistance(route.distance_meters)):`${e(guide.distance_km)} km`}</span></section><section class="place-routes"><div class="eyebrow">Ways to get there</div><h3>Choose what suits you</h3>${guide.modes.map(placeModeOption).join('')}</section><p class="place-freshness">${route?'Live route calculated by Google Maps from your device location. ':''}${e(guide.freshness.label)}. ${e(guide.assumption)}</p>`:`<section class="place-next-step"><div><div class="eyebrow">Location saved</div><h3>${e(commitment.location)}</h3><p>Add or verify a map location to see commute choices.</p></div></section>`}${relatedDocumentCards(commitment,commitment.type==='tour'?'Ticket and trip document':'Booking document')}</div></aside>`;}
function currentPosition(){return new Promise((resolve,reject)=>{if(!navigator.geolocation)return reject(Error('Location is unavailable in this browser.'));navigator.geolocation.getCurrentPosition(position=>resolve({lat:position.coords.latitude,lng:position.coords.longitude}),error=>reject(Error(error.code===1?'Location access was not allowed. Enable it to see live directions.':error.code===3?'Finding your location took too long. Please retry.':'Your current location could not be found.')),{enableHighAccuracy:false,timeout:10000,maximumAge:60000});});}
async function updateLiveRoute(mode,origin=null){if(!state.showPlace||state.locating)return;state.locating=true;state.routeError='';render();try{origin=origin||await currentPosition();state.liveRoute=await api(endpoint('route'),{commitment_id:state.showPlace,mode,origin});}catch(err){state.routeError=err.message;toast(err.message,true);}finally{state.locating=false;render();}}
function boardingPass(pass,{terminal,gate,seat,boarding,route}){const name=pass.traveler||pass.passenger_name||pass.passenger||'Traveler',group=pass.boarding_group||pass.group||'—',sequence=pass.sequence||pass.boarding_sequence||'',barcode=pass.barcode&&typeof pass.barcode==='object'?pass.barcode:{token:pass.barcode||pass.code||fact('flight.booking_reference',''),scannable:false},code=barcode.token||fact('flight.booking_reference','');return `<section class="boarding-pass"><div class="boarding-pass-top"><div><div class="eyebrow">${barcode.scannable?'Boarding pass':'Sample boarding pass'}</div><h3>${e(route)}</h3><p>${e(name)}</p></div><span class="pass-ready">Checked in</span></div><div class="boarding-pass-grid"><div><span>Boarding</span><strong>${e(clock(boarding,ORIGIN_ZONE))}</strong></div><div><span>Terminal</span><strong>${e(terminal)}</strong></div><div><span>Gate</span><strong>${e(gate)}</strong></div><div><span>Seat</span><strong>${e(seat)}</strong></div><div><span>Group</span><strong>${e(group)}</strong></div>${sequence?`<div><span>Sequence</span><strong>${e(sequence)}</strong></div>`:''}</div><div class="pass-code" aria-label="Boarding pass reference"><span aria-hidden="true"></span><small>${e(code)}</small><em>${e(pass.notice||'Demo reference only. Not valid for travel.')}</em></div></section>`;}
function recoveryChoiceButtons(t=state.trip){const p=currentPlan(t),chosen=currentAction(t);if(!p||chosen)return'';const feasible=p.result.options.filter(o=>o.feasible);if(!feasible.length)return'';return `<div class="chat-recovery"><div class="eyebrow">Ready when you are</div><strong>Choose how to continue</strong><p>Your flight delay breaks the original connection.</p>${feasible.map(o=>`<button class="chat-choice" data-action="approve" data-option="${e(o.id)}"><span>${e(o.mode==='train'?'Later train':o.mode==='taxi'?'Direct taxi':o.mode)}</span><small>$${e(o.cost)} extra · hotel ${e(clock(o.hotel_arrival))}</small><b>Review →</b></button>`).join('')}</div>`;}
function assistant(){return `<aside class="assistant open" aria-label="Trip assistant"><div class="sheet-handle"></div><div class="assistant-head"><div class="row"><span class="assistant-symbol">✦</span><div><h3>Ask about this trip</h3><div class="small">Answers use your reviewed trip documents</div></div></div><button class="close-sheet" data-action="assistant-toggle" aria-label="Close assistant">×</button></div><div class="chat" id="chat" role="log" aria-live="polite"></div><form class="compose" id="ask-form"><div class="compose-box"><textarea id="question" aria-label="Ask about your trip" placeholder="Ask what changed, what to do, or what may be covered…" maxlength="2000"></textarea><button class="send" type="submit" aria-label="Send question" ${state.pendingQuestion?'disabled':''}>↑</button></div><div class="compose-note">${state.asking?(state.pendingQuestion?'Your next question is queued':'Checking your trip — you can type your next question'):'Answers stay connected to your trip details and policies'}</div></form></aside>`;}
function renderChat(){const chat=$('#chat');if(!chat)return;const messages=state.trip.messages;if(!messages.length){chat.innerHTML=`<div class="chat-welcome"><div class="welcome-icon">✧</div><h2 class="serif">The whole trip.<br>The right context.</h2><p>I can explain bookings, personal plans, deadlines, and recovery choices — and show which document each detail came from.</p>${['Summarize my whole trip','Which of my plans are affected?','Could I be reimbursed?'].map(q=>`<button class="suggestion" data-action="ask-suggestion" data-question="${e(q)}">${e(q)}<span>↗</span></button>`).join('')}</div>`;}else{chat.innerHTML=messages.map(m=>`<div class="msg user">${e(m.question)}</div><div class="msg"><div class="msg-label">Based on your trip details${m.answer.revision!==state.trip.trip.revision?' · trip changed after this answer':''}</div>${e(m.answer.text)}<div style="white-space:normal">${m.answer.citations.map(c=>`<button class="citation" data-action="document" data-id="${c.id}">▤ ${e(c.name)}</button>`).join('')}</div></div>`).join('');}chat.innerHTML+=recoveryChoiceButtons();if(state.asking&&state.optimisticQuestion)chat.innerHTML+=`<div class="msg user optimistic">${e(state.optimisticQuestion)}</div><div class="answer-thinking"><span></span><span></span><span></span><b>Checking your trip</b></div>`;if(state.pendingQuestion)chat.innerHTML+=`<div class="msg user queued"><small>Next</small>${e(state.pendingQuestion)}</div>`;chat.scrollTop=chat.scrollHeight;}
function stopPlanSpeech(){if(speechInput){speechInput.onend=null;speechInput.stop();speechInput=null;}state.listening=false;}
function startPlanSpeech(){const Speech=window.SpeechRecognition||window.webkitSpeechRecognition;if(!Speech){toast('Voice input is unavailable in this browser. You can type your plan instead.');return;}if(speechInput&&state.listening){speechInput.stop();return;}const initial=state.planDraft.trim();speechInput=new Speech();speechInput.lang='en-US';speechInput.interimResults=true;speechInput.continuous=false;speechInput.onstart=()=>{state.listening=true;const button=$('.voice-button');if(button){button.classList.add('listening');button.innerHTML='<span>■</span>Listening…';button.setAttribute('aria-label','Stop listening');}};speechInput.onresult=event=>{let transcript='';for(let i=event.resultIndex;i<event.results.length;i++)transcript+=event.results[i][0].transcript;state.planDraft=[initial,transcript.trim()].filter(Boolean).join(initial&&transcript.trim()?' ':'');const input=$('#plan-text');if(input)input.value=state.planDraft;};speechInput.onerror=event=>{if(!['aborted','no-speech'].includes(event.error))toast('I could not hear that clearly. You can try again or type your plan.',true);};speechInput.onend=()=>{state.listening=false;speechInput=null;const button=$('.voice-button');if(button){button.classList.remove('listening');button.innerHTML='<span>●</span>Speak';button.setAttribute('aria-label','Add plan by voice');}};speechInput.start();}
function connections(){const c=state.health?.configuration||{},flightReady=c.flight_api!=='not_configured';return `<div class="heading"><div><div class="eyebrow">Trip settings</div><h1 class="serif" style="margin-top:10px">Wayfinder is ready.</h1><p>See what Wayfinder can handle for this trip.</p></div></div><div class="card"><div class="status-row"><span>Trip documents and policies</span>${tag(state.trip?.document_count?'Ready':'Add documents',state.trip?.document_count?'':'amber')}</div><div class="status-row"><span>Trip questions</span>${tag(c.cloud_enabled?'Ready':'Available')}</div><div class="status-row"><span>Flight updates</span>${tag(flightReady?'Watching while open':'Needs setup',flightReady?'':'amber')}</div><div class="status-row"><span>Booking changes</span>${tag('You approve first','gray')}</div><p class="footnote" style="margin-top:18px">Wayfinder never charges you or changes a reservation without confirmation.</p><button class="button secondary" data-action="refresh-health">Refresh status</button></div><details class="technical-details"><summary>Technical demo details</summary><div class="card"><div class="status-row"><span>Snowflake and Claude</span>${tag(c.cloud_enabled?'Connected':'Not connected',c.cloud_enabled?'':'amber')}</div><div class="status-row"><span>Flight data service</span>${tag(flightReady?'Connected':'Not connected',flightReady?'':'amber')}</div><div class="status-row"><span>Provider booking actions</span>${tag('Preview only','amber')}</div><p class="footnote">Reviewed, non-passport trip details are synced to Snowflake. Claude answers through the Snowflake Cortex Agent. The sample recovery inventory and booking confirmation are simulated.</p></div></details>`;}

async function ask(question){if(!state.trip)return;question=String(question||'').trim();if(!question)return;const input=$('#question');if(input)input.value='';if(state.asking){state.pendingQuestion=question;renderChat();return;}state.asking=true;state.optimisticQuestion=question;state.showAssistant=true;renderChat();try{await api(endpoint('ask'),{question,mode:state.mode});state.trip=await api('/api/trips/'+state.trip.trip.id);}catch(err){toast(err.message,true);}finally{state.asking=false;state.optimisticQuestion='';state.showAssistant=true;const queued=state.pendingQuestion;state.pendingQuestion='';render();$('#question')?.focus({preventScroll:true});if(queued)await ask(queued);}}
async function uploadFiles(files){if(state.uploading)return;state.uploading=true;state.tab='documents';render();let count=0;for(const file of files){try{if(file.size>10*1024*1024)throw Error(file.name+' exceeds 10 MB');const bytes=new Uint8Array(await file.arrayBuffer());let binary='';for(let i=0;i<bytes.length;i+=8192)binary+=String.fromCharCode(...bytes.subarray(i,i+8192));await api(endpoint('upload'),{name:file.name,content:btoa(binary)});count++;}catch(err){toast(file.name+': '+err.message,true);}}state.uploading=false;await refresh();if(count)toast(count+' document(s) added. Check the trip details we found.');}
function bindDrop(){const zone=$('#drop-zone');if(!zone)return;zone.addEventListener('dragover',ev=>{ev.preventDefault();zone.classList.add('dragging');});zone.addEventListener('dragleave',()=>zone.classList.remove('dragging'));zone.addEventListener('drop',ev=>{ev.preventDefault();zone.classList.remove('dragging');uploadFiles(ev.dataTransfer.files);});}
function openModal(html){$('#modal-content').innerHTML=html;$('#modal').showModal();}
function documentModal(id){const d=state.trip.documents.find(x=>x.id===id);if(!d){toast('This document is no longer available',true);return;}const itinerary=d.kind==='itinerary'&&Array.isArray(d.fields.items),details=itinerary?`<div class="doc-text">${d.fields.items.map(item=>`${e(item.title)} · ${e(fmt(item.start))}<br>${e(item.location)} · ${e(item.type)}`).join('<br><br>')}</div>`:`<div class="field-grid">${Object.entries(d.fields).map(([k,v])=>`<label class="field">${e(k.replaceAll('_',' '))}<input name="${e(k)}" value="${e(Array.isArray(v)?v.join(','):v===null?'unknown':String(v))}" maxlength="300"></label>`).join('')}</div>`;openModal(`<div class="modal-head"><div><div class="eyebrow">Trip document · ${e(d.kind)}</div><h2 class="serif" style="margin-top:7px">${e(d.name)}</h2></div><button class="close" data-action="close" aria-label="Close dialog">×</button></div><div class="row" style="margin-bottom:15px">${tag(d.state==='reviewed'?'Ready':'Check details',d.state==='reviewed'?'':'amber')}<span class="small">${d.pages.length} page(s)</span></div><details><summary class="small">View document text</summary><pre class="doc-text">${e(d.pages.map(p=>'PAGE '+p.page+'\n'+p.text).join('\n\n'))}</pre></details><form id="review-form" data-id="${d.id}"><p class="small" style="margin-top:18px">${itinerary?'Check each itinerary item against the uploaded document.':'Check these details against your document.'}</p>${details}${!Object.keys(d.fields).length?'<p class="footnote">We could not find trip details automatically. You can still keep this document as a reference.</p>':''}<div class="modal-actions"><button type="button" class="button danger" data-action="delete-document" data-id="${d.id}">Remove document</button><button class="button" type="submit">Save trip details ✓</button></div></form>`);}

document.addEventListener('click',async ev=>{const el=ev.target.closest('[data-action]');if(!el)return;const a=el.dataset.action;try{
 if(a==='manage-itineraries'){state.page='welcome';state.showAssistant=false;state.showNotifications=false;state.showAddPlans=false;state.showFlight=false;state.showTrain=false;state.showPlace=null;stopPlanSpeech();render();window.scrollTo({top:0,left:0,behavior:'auto'});}
 if(a==='page'){state.page=el.dataset.page;state.showAssistant=false;state.showAddPlans=false;state.showFlight=false;state.showTrain=false;state.showPlace=null;stopPlanSpeech();render();}
 if(a==='tab'){state.tab=el.dataset.tab;state.showAddPlans=false;state.showFlight=false;state.showTrain=false;state.showPlace=null;stopPlanSpeech();render();}
 if(a==='mobile-tab'){state.page='trips';state.tab=el.dataset.tab;state.showAssistant=false;state.showAddPlans=false;state.showFlight=false;state.showTrain=false;state.showPlace=null;stopPlanSpeech();render();window.scrollTo({top:0,behavior:'smooth'});}
 if(a==='assistant-toggle'){state.showAssistant=!state.showAssistant;state.showFlight=false;state.showTrain=false;render();}
 if(a==='notifications-toggle'){state.showNotifications=!state.showNotifications;state.showAssistant=false;state.showFlight=false;state.showTrain=false;render();}
 if(a==='add-plans-toggle'){state.showAddPlans=!state.showAddPlans;state.showAssistant=false;state.showNotifications=false;state.showFlight=false;state.showTrain=false;if(!state.showAddPlans)stopPlanSpeech();render();if(state.showAddPlans)setTimeout(()=>$('#plan-text')?.focus({preventScroll:true}),0);}
 if(a==='flight-toggle'){state.showFlight=!state.showFlight;state.showTrain=false;state.showAssistant=false;state.showNotifications=false;state.showAddPlans=false;render();}
 if(a==='train-toggle'){state.showTrain=!state.showTrain;state.showFlight=false;state.showAssistant=false;state.showNotifications=false;state.showAddPlans=false;render();}
 if(a==='place-toggle'){state.showPlace=el.dataset.id||null;state.liveRoute=null;state.routeError='';state.showFlight=false;state.showTrain=false;state.showAssistant=false;state.showNotifications=false;state.showAddPlans=false;render();}
 if(a==='place-close'){state.showPlace=null;state.liveRoute=null;state.routeError='';render();}
 if(a==='live-place-route')await updateLiveRoute(el.dataset.mode||'transit');
 if(a==='live-place-mode')await updateLiveRoute(el.dataset.mode||'transit',state.liveRoute?.origin||null);
 if(a==='place-mode'){const guide=placeExperience(state.showPlace),commitment=tripCommitments().find(item=>item.id===state.showPlace),mode=el.dataset.mode||'this route';state.showPlace=null;state.showAssistant=true;render();await ask(`For ${commitment?.title||'this plan'}, explain whether ${mode} is the best way to get from ${guide?.origin?.name||'my stay'} to ${guide?.destination?.name||'the destination'}.`);}
 if(a==='flight-recovery'){state.showFlight=false;state.tab='recovery';render();window.scrollTo({top:0,behavior:'smooth'});}
 if(a==='train-recovery'){state.showTrain=false;state.tab='recovery';render();window.scrollTo({top:0,behavior:'smooth'});}
 if(a==='train-ask'||a==='train-option'){const mode=el.dataset.mode||'',question=el.dataset.question||`Would ${mode} be a good way to reach my destination from the train station?`;state.showTrain=false;state.showAssistant=true;render();await ask(question);}
 if(a==='flight-check-in'){state.busy=true;render();try{const result=await api(endpoint('check-in'),{checked_in:true});state.trip=result?.trip?.id?result:result?.snapshot?.trip?.id?result.snapshot:await api('/api/trips/'+state.trip.trip.id);toast('Demo check-in saved. Your sample boarding pass is ready.');}finally{state.busy=false;state.showFlight=true;render();}}
 if(a==='plan-example'){state.planDraft=el.dataset.text||'';const input=$('#plan-text');if(input){input.value=state.planDraft;input.focus({preventScroll:true});}}
 if(a==='voice-plan')startPlanSpeech();
 if(a==='remove-plan'){el.outerHTML=`<button class="remove-plan confirm" data-action="confirm-remove-plan" data-id="${e(el.dataset.id)}">Remove this plan?</button>`;}
 if(a==='confirm-remove-plan'){el.disabled=true;const result=await api(endpoint('commitment'),{id:el.dataset.id,delete:true});state.trip=result?.trip?.id?result:await api('/api/trips/'+state.trip.trip.id);render();toast('Plan removed from your itinerary.');}
 if(a==='enable-notifications'){if(typeof Notification==='undefined')throw Error('Browser alerts are unavailable here');const permission=await Notification.requestPermission();render();if(permission!=='granted')toast('Browser alerts were not enabled. In-app notifications remain available.');}
 if(a==='check-flight'){state.busy=true;render();try{state.liveStatus=await api(endpoint('check-flight'),{});state.trip=await api('/api/trips/'+state.trip.trip.id);render();toast('Flight status updated.');}finally{state.busy=false;render();}}
 if(a==='select-trip')await selectTrip(el.dataset.id);
 if(a==='open-existing'){state.page='trips';render();startMonitoring();startSampleMonitor();}
 if(a==='connect-email')openModal(`<div class="modal-head"><div><div class="eyebrow">Connect email</div><h2>Find your bookings</h2></div><button class="close" data-action="close" aria-label="Close dialog">×</button></div><p>In the full product, you would choose Gmail or Outlook and approve read-only access to booking confirmations.</p><div class="email-providers"><button class="provider-row" disabled><span>G</span><div><strong>Google Gmail</strong><small>Connection not enabled in this local demo</small></div></button><button class="provider-row" disabled><span>O</span><div><strong>Microsoft Outlook</strong><small>Connection not enabled in this local demo</small></div></button></div><button class="button sample-inbox" data-action="load-demo">Try with the sample inbox →</button><p class="footnote">The sample uses fictional confirmation emails and makes no external account connection.</p>`);
 if(a==='onboard-documents')openModal(`<div class="modal-head"><div><div class="eyebrow">Add documents</div><h2>Create your itinerary</h2></div><button class="close" data-action="close" aria-label="Close dialog">×</button></div><form id="document-trip-form"><label class="field">Trip name<input name="title" placeholder="London conference trip" maxlength="100" required></label><p class="footnote" style="margin-top:14px">Next, add up to 15 flight, hotel, train, activity, or policy documents.</p><button class="button" type="submit">Create and add documents →</button></form>`);
 if(a==='load-demo'){el.disabled=true;const existing=state.trips.find(trip=>trip.scenario==='heathrow-demo'),snap=existing?await api('/api/trips/'+existing.id):await api('/api/trips',{title:'A long weekend in London',demo:true,full_demo:true});state.trip=snap;state.liveStatus=null;state.tab='overview';state.page='trips';if($('#modal')?.open)$('#modal').close();await refresh();toast(existing?'Your sample itinerary is open.':'Sample itinerary created. Wayfinder is now watching it.');startSampleMonitor();}
 if(a==='new-trip')openModal('<div class="modal-head"><h2 class="serif">Start a new journey</h2><button class="close" data-action="close" aria-label="Close dialog">×</button></div><form id="new-trip-form"><label class="field">Itinerary name<input name="title" placeholder="A week in Copenhagen" maxlength="100" required></label><p class="footnote" style="margin-top:14px">Add flight, hotel, train, and card documents to bring this trip together.</p><button class="button" type="submit">Create itinerary →</button></form>');
 if(a==='close')$('#modal').close();
 if(a==='upload-click'){state.showTrain=false;state.tab='documents';render();$('#file-input').click();}
 if(a==='document')documentModal(el.dataset.id);
 if(a==='ask-suggestion'){state.showAssistant=true;render();await ask(el.dataset.question);}
 if(a==='budget-edit')openModal(`<div class="modal-head"><h2 class="serif">Maximum extra spend</h2><button class="close" data-action="close" aria-label="Close dialog">×</button></div><form id="budget-form"><label class="field">Amount in USD<input name="amount" type="number" min="0" max="100000" value="${state.trip.trip.budget}" required></label><p class="footnote" style="margin-top:14px">Wayfinder uses this limit when it compares disruption choices.</p><button class="button" type="submit">Save spending limit</button></form>`);
 if(a==='refresh-health'){state.health=await api('/api/health');render();toast('App status refreshed.');}
 if(a==='delete-document'){el.outerHTML=`<button type="button" class="button danger" data-action="confirm-delete" data-id="${el.dataset.id}">Confirm removal?</button>`;}
 if(a==='confirm-delete'){await api(endpoint('delete-document'),{document_id:el.dataset.id});$('#modal').close();await refresh();toast('Document removed. Trip guidance has been refreshed.');}
 if(a==='approve'){const p=currentPlan(),o=p.result.options.find(x=>x.id===el.dataset.option);openModal(`<div class="modal-head"><h2 class="serif">Confirm this choice</h2><button class="close" data-action="close" aria-label="Close dialog">×</button></div><p>Take the <strong>${e(o.mode)}</strong> for <strong>$${o.cost} extra</strong> and arrive at the hotel at <strong>${e(clock(o.hotel_arrival))}</strong>.</p><p class="small">For this sample, Wayfinder saves the choice but does not buy a ticket, cancel a reservation, or charge you.</p><div class="modal-actions"><button class="button secondary" data-action="close">Go back</button><button class="button" data-action="confirm-approve" data-plan="${p.id}" data-option="${o.id}">Confirm choice ✓</button></div>`);}
 if(a==='confirm-approve'){el.disabled=true;await api(endpoint('approve'),{plan_id:el.dataset.plan,option_id:el.dataset.option});$('#modal').close();state.tab='overview';await refresh();toast('Choice saved. No booking was made in this sample.');}
 if(a==='demo-disruption'){state.busy=true;render();const id=state.trip.trip.id,key=Date.now();try{await api(`/api/trips/${id}/replay`,{minutes:0,cause:'weather',event_key:`${id}-presenter-on-${key}`});await wait(700);await api(`/api/trips/${id}/replay`,{minutes:120,cause:'weather',event_key:`${id}-presenter-delay-${key}`});state.trip=await api('/api/trips/'+id);render();notifyRecovery();toast('Flight update received. Recovery choices are ready.');}finally{state.busy=false;render();}}
 }catch(err){toast(err.message,true);el.disabled=false;}});
document.addEventListener('submit',async ev=>{ev.preventDefault();try{
 if(ev.target.id==='ask-form')await ask($('#question').value);
 if(ev.target.id==='add-plan-form'){const text=String(new FormData(ev.target).get('text')||'').trim();if(!text)throw Error('Tell Wayfinder what you are planning.');state.planDraft=text;state.busy=true;stopPlanSpeech();render();try{const result=await api(endpoint('commitment'),{text});state.trip=result?.trip?.id?result:result?.snapshot?.trip?.id?result.snapshot:await api('/api/trips/'+state.trip.trip.id);state.planDraft='';state.showAddPlans=false;toast('Plan added. Wayfinder will include it when your trip changes.');}finally{state.busy=false;render();}}
 if(ev.target.id==='document-trip-form'){const title=new FormData(ev.target).get('title');state.trip=await api('/api/trips',{title});state.liveStatus=null;state.page='trips';state.tab='documents';$('#modal').close();await refresh();setTimeout(()=>$('#file-input')?.click(),0);}
 if(ev.target.id==='new-trip-form'){const title=new FormData(ev.target).get('title');state.trip=await api('/api/trips',{title});state.liveStatus=null;$('#modal').close();state.tab='documents';await refresh();}
 if(ev.target.id==='budget-form'){const amount=Number(new FormData(ev.target).get('amount'));await api(endpoint('budget'),{amount});$('#modal').close();await refresh();toast('Spending limit saved.');}
 if(ev.target.id==='review-form'){const d=state.trip.documents.find(x=>x.id===ev.target.dataset.id),fields=d.kind==='itinerary'?d.fields:Object.fromEntries(new FormData(ev.target));await api(endpoint('review'),{document_id:d.id,kind:d.kind,fields});$('#modal').close();await refresh();toast('Trip details saved.');}
 }catch(err){state.busy=false;toast(err.message,true);render();}});
document.addEventListener('change',ev=>{if(ev.target.id==='file-input')uploadFiles(ev.target.files);});
document.addEventListener('input',ev=>{if(ev.target.id==='plan-text')state.planDraft=ev.target.value;});
document.addEventListener('keydown',ev=>{if(ev.target.id==='question'&&ev.key==='Enter'&&!ev.shiftKey){ev.preventDefault();ask(ev.target.value);}else if(ev.target.matches('.interactive-journey')&&['Enter',' '].includes(ev.key)){ev.preventDefault();ev.target.click();}});
async function init(){try{state.health=await api('/api/health');state.mode=state.health.configuration.cloud_enabled?'cortex':'local';state.trips=await api('/api/trips');if(state.trips.length)state.trip=await api('/api/trips/'+state.trips[0].id);render();window.scrollTo({top:0,left:0,behavior:'auto'});countdownTimer=setInterval(updateLeaveCountdowns,1000);startMonitoring();startSampleMonitor();}catch(err){$('#app').innerHTML=`<div class="empty"><h1 class="serif">Wayfinder couldn’t load.</h1><p>${e(err.message)}</p><button class="button" data-action="reload">Try again</button></div>`;document.querySelector('[data-action="reload"]').onclick=()=>location.reload();}}
init();
